#include "minirt.h"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "short";
    int n = argc > 2 ? atoi(argv[2]) : 100000;
    uint64_t sum = 0;
    for (int j = 0; j < n; j++) {
        MkObject *sb = mk_sb_new();
        if (mode[0] == 's') {
            for (int i = 0; i < 8; i++) mk_sb_append_char(sb, (MkChar)('a' + i));
        } else if (mode[0] == '1') {
            for (int i = 0; i < 16; i++) mk_sb_append_char(sb, (MkChar)('a' + i));
        } else if (mode[0] == '7') {
            for (int i = 0; i < 17; i++) mk_sb_append_char(sb, (MkChar)('a' + i));
        } else if (mode[0] == 'l') {
            for (int i = 0; i < 1024; i++) mk_sb_append_char(sb, (MkChar)('a' + i % 26));
        } else if (mode[0] == 'n') {
            mk_sb_append_long(sb, INT64_MIN);
            mk_sb_append_long(sb, INT64_MAX);
        }
        MkString *str = mk_sb_to_string(sb);
        if (str->length > 0) sum += (uint16_t)mk_string_char_at(str, str->length - 1);
        sum += (uint64_t)str->length;
        mk_release(&str->header);
        mk_release(sb);
    }
    printf("%s %d %llu\n", mode, n, (unsigned long long)sum);
    return 0;
}
